/* @autogenerated */
package net.civeira.phylax.features.oauth.delegatelogin.domain.provider;

import java.io.ByteArrayInputStream;
import java.security.PublicKey;
import java.time.Duration;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.ArrayList;
import java.util.Base64;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.Set;

import javax.xml.XMLConstants;
import javax.xml.crypto.dsig.CanonicalizationMethod;
import javax.xml.crypto.dsig.Reference;
import javax.xml.crypto.dsig.Transform;
import javax.xml.crypto.dsig.XMLSignature;
import javax.xml.crypto.dsig.XMLSignatureFactory;
import javax.xml.crypto.dsig.dom.DOMValidateContext;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;

import org.w3c.dom.Document;
import org.w3c.dom.Element;
import org.w3c.dom.Node;
import org.w3c.dom.NodeList;

import lombok.Builder;
import lombok.Getter;
import lombok.NonNull;

/**
 * Strict validation of a SAML 2.0 Web Browser SSO response (HTTP-POST binding).
 *
 * Responsibilities: - Verify the XML signature of the response or of the assertion that is used. -
 * Check issuer, audience, destination, recipient, validity window and InResponseTo.
 *
 * Design notes: - Same checks as php-saml in strict mode, on the JDK XML DSig implementation with
 * secure validation. - Accepts exactly one unencrypted assertion, direct child of the response, so
 * a signed element cannot be wrapped next to an unsigned one. - Unsolicited responses (without
 * InResponseTo) are rejected.
 */
public final class SamlResponseValidator {
  /**
   * SAML protocol namespace.
   */
  static final String PROTOCOL = "urn:oasis:names:tc:SAML:2.0:protocol";
  /**
   * SAML assertion namespace.
   */
  static final String ASSERTION = "urn:oasis:names:tc:SAML:2.0:assertion";
  /**
   * Status code of a successful response.
   */
  private static final String SUCCESS = "urn:oasis:names:tc:SAML:2.0:status:Success";
  /**
   * Subject confirmation method of the Web Browser SSO profile.
   */
  private static final String BEARER = "urn:oasis:names:tc:SAML:2.0:cm:bearer";
  /**
   * Largest decoded response accepted.
   */
  private static final int MAX_BYTES = 256 * 1024;
  /**
   * Transforms allowed in the signature reference.
   */
  private static final Set<String> ALLOWED_TRANSFORMS = Set.of(Transform.ENVELOPED,
      CanonicalizationMethod.EXCLUSIVE, CanonicalizationMethod.EXCLUSIVE_WITH_COMMENTS);

  /**
   * What the response must match.
   */
  @Getter
  @Builder
  public static class Expectations {
    /**
     * Public key of the IdP certificate configured for the provider.
     */
    @NonNull
    private final PublicKey idpKey;
    /**
     * Entity ID of the IdP.
     */
    @NonNull
    private final String idpEntityId;
    /**
     * Entity ID of this service provider (the expected audience).
     */
    @NonNull
    private final String spEntityId;
    /**
     * Assertion consumer service URL (expected Destination and Recipient).
     */
    @NonNull
    private final String acsUrl;
    /**
     * ID of the AuthnRequest that the response must answer.
     */
    @NonNull
    private final String requestId;
    /**
     * Current instant.
     */
    @NonNull
    private final Instant now;
    /**
     * Allowed clock skew.
     */
    @Builder.Default
    private final Duration skew = Duration.ofMinutes(2);
  }

  /**
   * Data of a validated assertion.
   */
  @Getter
  @Builder
  public static class ValidAssertion {
    /**
     * Subject NameID.
     */
    private final String nameId;
    /**
     * Attributes by name, in document order.
     */
    private final Map<String, List<String>> attributes;

    /**
     * Returns the first non blank value of the first attribute present.
     *
     * @param names candidate attribute names
     * @return value
     */
    public Optional<String> firstAttribute(List<String> names) {
      for (String name : names) {
        List<String> values = attributes.getOrDefault(name, List.of());
        for (String value : values) {
          if (value != null && !value.isBlank()) {
            return Optional.of(value.trim());
          }
        }
      }
      return Optional.empty();
    }
  }

  /**
   * Reason why a response is rejected.
   */
  public static class SamlValidationException extends Exception {
    private static final long serialVersionUID = 1L;

    /**
     * Creates the exception.
     *
     * @param message reason
     */
    public SamlValidationException(String message) {
      super(message);
    }

    /**
     * Creates the exception with its cause.
     *
     * @param message reason
     * @param cause cause
     */
    public SamlValidationException(String message, Throwable cause) {
      super(message, cause);
    }
  }

  private SamlResponseValidator() {}

  /**
   * Validates a base64 encoded SAMLResponse.
   *
   * @param samlResponse value of the SAMLResponse form field
   * @param expected values the response must match
   * @return validated assertion data
   * @throws SamlValidationException when any check fails
   */
  public static ValidAssertion validate(String samlResponse, Expectations expected)
      throws SamlValidationException {
    Document document = parse(decode(samlResponse));
    Element response = document.getDocumentElement();
    if (!is(response, PROTOCOL, "Response")) {
      throw new SamlValidationException("Root element is not a SAML Response");
    }
    registerIds(document);
    checkStatus(response);
    if (!expected.getRequestId().equals(response.getAttribute("InResponseTo"))) {
      throw new SamlValidationException("Response does not answer the request sent");
    }
    String destination = response.getAttribute("Destination");
    if (!destination.isEmpty() && !expected.getAcsUrl().equals(destination)) {
      throw new SamlValidationException("Response destination is not this service");
    }
    Optional<Element> responseIssuer = child(response, ASSERTION, "Issuer");
    if (responseIssuer.isPresent()
        && !expected.getIdpEntityId().equals(text(responseIssuer.get()))) {
      throw new SamlValidationException("Response issuer is not the configured IdP");
    }
    if (document.getElementsByTagNameNS(ASSERTION, "EncryptedAssertion").getLength() > 0) {
      throw new SamlValidationException("Encrypted assertions are not supported");
    }
    NodeList assertions = document.getElementsByTagNameNS(ASSERTION, "Assertion");
    if (assertions.getLength() != 1 || assertions.item(0).getParentNode() != response) {
      throw new SamlValidationException("Response must contain exactly one assertion");
    }
    Element assertion = (Element) assertions.item(0);

    boolean responseSigned = signedBy(response, expected.getIdpKey());
    boolean assertionSigned = signedBy(assertion, expected.getIdpKey());
    if (!responseSigned && !assertionSigned) {
      throw new SamlValidationException("Neither the response nor the assertion is signed");
    }
    if (responseSigned && destination.isEmpty()) {
      throw new SamlValidationException("Signed response without destination");
    }

    Element issuer = child(assertion, ASSERTION, "Issuer")
        .orElseThrow(() -> new SamlValidationException("Assertion without issuer"));
    if (!expected.getIdpEntityId().equals(text(issuer))) {
      throw new SamlValidationException("Assertion issuer is not the configured IdP");
    }
    String nameId = checkSubject(assertion, expected);
    checkConditions(assertion, expected);
    checkAuthnStatements(assertion, expected);
    return ValidAssertion.builder().nameId(nameId).attributes(attributes(assertion)).build();
  }

  private static byte[] decode(String samlResponse) throws SamlValidationException {
    if (samlResponse == null || samlResponse.isBlank()) {
      throw new SamlValidationException("Empty SAMLResponse");
    }
    if (samlResponse.length() > MAX_BYTES * 2) {
      throw new SamlValidationException("SAMLResponse too large");
    }
    try {
      byte[] decoded = Base64.getMimeDecoder().decode(samlResponse);
      if (decoded.length > MAX_BYTES) {
        throw new SamlValidationException("SAMLResponse too large");
      }
      return decoded;
    } catch (IllegalArgumentException ex) {
      throw new SamlValidationException("SAMLResponse is not base64", ex);
    }
  }

  private static Document parse(byte[] xml) throws SamlValidationException {
    try {
      DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
      factory.setNamespaceAware(true);
      factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
      factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
      factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
      factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
      factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
      factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
      factory.setXIncludeAware(false);
      factory.setExpandEntityReferences(false);
      DocumentBuilder builder = factory.newDocumentBuilder();
      builder.setErrorHandler(null);
      return builder.parse(new ByteArrayInputStream(xml));
    } catch (Exception ex) {
      throw new SamlValidationException("SAMLResponse is not valid XML", ex);
    }
  }

  /**
   * Marks every {@code ID} attribute as an XML ID and rejects duplicates, so that a signature
   * reference resolves to a single element.
   */
  private static void registerIds(Document document) throws SamlValidationException {
    Set<String> seen = new HashSet<>();
    NodeList all = document.getElementsByTagNameNS("*", "*");
    for (int i = 0; i < all.getLength(); i++) {
      Element element = (Element) all.item(i);
      if (element.hasAttributeNS(null, "ID")) {
        String id = element.getAttributeNS(null, "ID");
        if (!seen.add(id)) {
          throw new SamlValidationException("Duplicated ID in SAMLResponse");
        }
        element.setIdAttributeNS(null, "ID", true);
      }
    }
  }

  private static void checkStatus(Element response) throws SamlValidationException {
    Element status = child(response, PROTOCOL, "Status")
        .orElseThrow(() -> new SamlValidationException("Response without status"));
    Element code = child(status, PROTOCOL, "StatusCode")
        .orElseThrow(() -> new SamlValidationException("Response without status code"));
    if (!SUCCESS.equals(code.getAttribute("Value"))) {
      throw new SamlValidationException("Response status is not success");
    }
  }

  /**
   * Checks the enveloped signature that is a direct child of the element and references it.
   *
   * @return false when the element has no signature; true when it has a valid one
   * @throws SamlValidationException when the signature is present but invalid
   */
  private static boolean signedBy(Element element, PublicKey key) throws SamlValidationException {
    List<Element> signatures = children(element, XMLSignature.XMLNS, "Signature");
    if (signatures.isEmpty()) {
      return false;
    }
    if (signatures.size() > 1) {
      throw new SamlValidationException("More than one signature on " + element.getLocalName());
    }
    String id = element.getAttributeNS(null, "ID");
    if (id.isEmpty()) {
      throw new SamlValidationException("Signed element without ID");
    }
    try {
      DOMValidateContext context = new DOMValidateContext(key, signatures.get(0));
      context.setProperty("org.jcp.xml.dsig.secureValidation", Boolean.TRUE);
      XMLSignature signature =
          XMLSignatureFactory.getInstance("DOM").unmarshalXMLSignature(context);
      List<?> references = signature.getSignedInfo().getReferences();
      if (references.size() != 1) {
        throw new SamlValidationException("Signature must have exactly one reference");
      }
      Reference reference = (Reference) references.get(0);
      if (!("#" + id).equals(reference.getURI())) {
        throw new SamlValidationException("Signature does not reference its element");
      }
      for (Object transform : reference.getTransforms()) {
        if (!ALLOWED_TRANSFORMS.contains(((Transform) transform).getAlgorithm())) {
          throw new SamlValidationException("Signature transform not allowed");
        }
      }
      if (!signature.validate(context)) {
        throw new SamlValidationException("Invalid signature on " + element.getLocalName());
      }
      return true;
    } catch (SamlValidationException ex) {
      throw ex;
    } catch (Exception ex) {
      throw new SamlValidationException("Unable to verify signature", ex);
    }
  }

  private static String checkSubject(Element assertion, Expectations expected)
      throws SamlValidationException {
    Element subject = child(assertion, ASSERTION, "Subject")
        .orElseThrow(() -> new SamlValidationException("Assertion without subject"));
    String nameId = child(subject, ASSERTION, "NameID").map(SamlResponseValidator::text)
        .filter(value -> !value.isEmpty())
        .orElseThrow(() -> new SamlValidationException("Assertion without NameID"));
    boolean confirmed = false;
    for (Element confirmation : children(subject, ASSERTION, "SubjectConfirmation")) {
      if (!BEARER.equals(confirmation.getAttribute("Method"))) {
        continue;
      }
      Optional<Element> data = child(confirmation, ASSERTION, "SubjectConfirmationData");
      if (data.isEmpty()) {
        continue;
      }
      Element value = data.get();
      boolean recipient = expected.getAcsUrl().equals(value.getAttribute("Recipient"));
      boolean answers = expected.getRequestId().equals(value.getAttribute("InResponseTo"));
      boolean alive = after(value.getAttribute("NotOnOrAfter"), expected, true);
      boolean started = value.getAttribute("NotBefore").isEmpty()
          || notAfter(value.getAttribute("NotBefore"), expected);
      if (recipient && answers && alive && started) {
        confirmed = true;
        break;
      }
    }
    if (!confirmed) {
      throw new SamlValidationException("No valid bearer subject confirmation");
    }
    return nameId;
  }

  private static void checkConditions(Element assertion, Expectations expected)
      throws SamlValidationException {
    Element conditions = child(assertion, ASSERTION, "Conditions")
        .orElseThrow(() -> new SamlValidationException("Assertion without conditions"));
    String notBefore = conditions.getAttribute("NotBefore");
    if (!notBefore.isEmpty() && !notAfter(notBefore, expected)) {
      throw new SamlValidationException("Assertion is not yet valid");
    }
    String notOnOrAfter = conditions.getAttribute("NotOnOrAfter");
    if (!notOnOrAfter.isEmpty() && !after(notOnOrAfter, expected, true)) {
      throw new SamlValidationException("Assertion is no longer valid");
    }
    List<Element> restrictions = children(conditions, ASSERTION, "AudienceRestriction");
    if (restrictions.isEmpty()) {
      throw new SamlValidationException("Assertion without audience restriction");
    }
    // Every AudienceRestriction must name this service provider (SAML core 2.5.1.4).
    for (Element restriction : restrictions) {
      boolean found = false;
      for (Element audience : children(restriction, ASSERTION, "Audience")) {
        if (expected.getSpEntityId().equals(text(audience))) {
          found = true;
        }
      }
      if (!found) {
        throw new SamlValidationException("Assertion audience is not this service");
      }
    }
  }

  private static void checkAuthnStatements(Element assertion, Expectations expected)
      throws SamlValidationException {
    for (Element statement : children(assertion, ASSERTION, "AuthnStatement")) {
      String sessionEnd = statement.getAttribute("SessionNotOnOrAfter");
      if (!sessionEnd.isEmpty() && !after(sessionEnd, expected, true)) {
        throw new SamlValidationException("IdP session already expired");
      }
    }
  }

  private static Map<String, List<String>> attributes(Element assertion) {
    Map<String, List<String>> result = new LinkedHashMap<>();
    for (Element statement : children(assertion, ASSERTION, "AttributeStatement")) {
      for (Element attribute : children(statement, ASSERTION, "Attribute")) {
        List<String> values =
            result.computeIfAbsent(attribute.getAttribute("Name"), name -> new ArrayList<>());
        for (Element value : children(attribute, ASSERTION, "AttributeValue")) {
          values.add(text(value));
        }
      }
    }
    return result;
  }

  /**
   * True when the instant is later than now (minus skew when lenient).
   */
  private static boolean after(String value, Expectations expected, boolean required)
      throws SamlValidationException {
    if (value.isEmpty()) {
      return !required;
    }
    return instant(value).isAfter(expected.getNow().minus(expected.getSkew()));
  }

  /**
   * True when the instant is not later than now plus skew.
   */
  private static boolean notAfter(String value, Expectations expected)
      throws SamlValidationException {
    return !instant(value).isAfter(expected.getNow().plus(expected.getSkew()));
  }

  private static Instant instant(String value) throws SamlValidationException {
    try {
      return Instant.parse(value);
    } catch (DateTimeParseException ex) {
      throw new SamlValidationException("Invalid instant " + value, ex);
    }
  }

  private static boolean is(Element element, String namespace, String name) {
    return namespace.equals(element.getNamespaceURI()) && name.equals(element.getLocalName());
  }

  private static Optional<Element> child(Element parent, String namespace, String name)
      throws SamlValidationException {
    List<Element> found = children(parent, namespace, name);
    if (found.size() > 1) {
      throw new SamlValidationException("Repeated " + name + " in " + parent.getLocalName());
    }
    return found.stream().findFirst();
  }

  private static List<Element> children(Element parent, String namespace, String name) {
    List<Element> result = new ArrayList<>();
    for (Node node = parent.getFirstChild(); node != null; node = node.getNextSibling()) {
      if (node instanceof Element element && is(element, namespace, name)) {
        result.add(element);
      }
    }
    return result;
  }

  private static String text(Element element) {
    return element.getTextContent() == null ? "" : element.getTextContent().trim();
  }
}
